import{_ as e,o,c as a,a2 as i}from"./chunks/framework.RycU2wFZ.js";const h=JSON.parse('{"title":"ADR-001: Architectural Strategy for x402 V2 Protocol & Official SDK (\\"Reuse vs. Custom Implementation\\")","description":"","frontmatter":{},"headers":[],"relativePath":"zh/specs/adr/001.md","filePath":"zh/specs/adr/001.md","lastUpdated":null}'),n={name:"zh/specs/adr/001.md"};function r(l,t,s,c,d,g){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="adr-001-architectural-strategy-for-x402-v2-protocol-official-sdk-reuse-vs-custom-implementation" tabindex="-1">ADR-001: Architectural Strategy for x402 V2 Protocol &amp; Official SDK (&quot;Reuse vs. Custom Implementation&quot;) <a class="header-anchor" href="#adr-001-architectural-strategy-for-x402-v2-protocol-official-sdk-reuse-vs-custom-implementation" aria-label="Permalink to &quot;ADR-001: Architectural Strategy for x402 V2 Protocol &amp; Official SDK (&quot;Reuse vs. Custom Implementation&quot;)&quot;">​</a></h1><ul><li><strong>Status:</strong> Accepted</li><li><strong>Date:</strong> 2026-10-16</li><li><strong>Deciders:</strong> AgentPay Core Architecture Working Group</li><li><strong>Task References:</strong> 2026 Year-End Plan (Tasks T0.2, T3.1)</li></ul><hr><h2 id="_1-context-problem-statement" tabindex="-1">1. Context &amp; Problem Statement <a class="header-anchor" href="#_1-context-problem-statement" aria-label="Permalink to &quot;1. Context &amp; Problem Statement&quot;">​</a></h2><p>x402 is an open standard protocol for HTTP 402 Payment Required micro-payments (maintained by the x402 Foundation). In the current 2026 ecosystem:</p><ol><li><strong>Protocol Specification State:</strong> The x402 V2 specification defines CAIP-2 chain identifiers, EIP-712/3009 transfer authorizations, and structured <code>PAYMENT-REQUIRED</code> and <code>PAYMENT-SIGNATURE</code> headers.</li><li><strong>Official Python SDK State:</strong> A baseline <code>x402</code> package exists on PyPI (with optional extras such as <code>x402[httpx]</code> and <code>x402[requests]</code>), offering basic challenge extraction and raw signing bindings.</li><li><strong>AgentPay Core Differentiation:</strong><ul><li>The official SDK functions as a <strong>Raw Transport Wrapper</strong>: whenever it encounters an HTTP 402, it signs and pays unconditionally.</li><li>AgentPay is designed as an <strong>Autonomous Financial Firewall &amp; Fault-Tolerant Infrastructure Layer</strong>: its primary value proposition lies in <strong>deterministic policy evaluation (per-tx caps, rolling budgets, whitelists, loop circuit breakers, and two-phase atomic reservations)</strong> and a <strong>decoupled tri-state recovery engine</strong>.</li></ul></li></ol><hr><h2 id="_2-options-considered" tabindex="-1">2. Options Considered <a class="header-anchor" href="#_2-options-considered" aria-label="Permalink to &quot;2. Options Considered&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Evaluation Dimension</th><th style="text-align:left;">Option A: Hard Dependency on Official SDK (<code>x402</code>)</th><th style="text-align:left;">Option B: Full Scratch Implementation from Zero</th><th style="text-align:left;">Option C (Recommended): Layered Adaptation with Custom Firewall Core</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Financial Firewall Integration</strong></td><td style="text-align:left;">Difficult. Official interceptor lacks hooks for two-phase reservation (<code>reserve -&gt; commit -&gt; release</code>).</td><td style="text-align:left;">Complete autonomy; interceptor seamlessly coordinates with policy engine.</td><td style="text-align:left;"><strong>Excellent.</strong> Full lifecycle interceptor with exact protocol format alignment.</td></tr><tr><td style="text-align:left;"><strong>Dependency Footprint</strong></td><td style="text-align:left;">Heavy. Transitive web3 and cryptography version conflicts.</td><td style="text-align:left;">Minimal (<code>httpx</code>, <code>pydantic</code>, <code>eth-account</code>).</td><td style="text-align:left;"><strong>Minimal.</strong> Core package has zero extraneous dependencies; official SDK is purely optional.</td></tr><tr><td style="text-align:left;"><strong>Specification Upstream Parity</strong></td><td style="text-align:left;">Automatically inherits upstream patches.</td><td style="text-align:left;">Manual alignment required if protocol headers change.</td><td style="text-align:left;"><strong>High.</strong> Standard Pydantic schema validated against upstream test vectors.</td></tr><tr><td style="text-align:left;"><strong>Implementation Risk &amp; Velocity</strong></td><td style="text-align:left;">Low initial velocity; high risk when retrofitting firewall state machine.</td><td style="text-align:left;">Moderate (approx. 200 lines of Pydantic codecs).</td><td style="text-align:left;"><strong>Optimal (approx. 3 hours for clean schema; zero black-box debugging).</strong></td></tr></tbody></table><hr><h2 id="_3-decision-outcome" tabindex="-1">3. Decision Outcome <a class="header-anchor" href="#_3-decision-outcome" aria-label="Permalink to &quot;3. Decision Outcome&quot;">​</a></h2><p>We decided to adopt <strong>Option C (Layered Adaptation Architecture)</strong>:</p><h3 id="_3-1-core-protocol-codec-agentpay-core-—-clean-pydantic-v2-models" tabindex="-1">3.1 Core Protocol Codec (<code>agentpay-core</code>) — Clean Pydantic V2 Models <a class="header-anchor" href="#_3-1-core-protocol-codec-agentpay-core-—-clean-pydantic-v2-models" aria-label="Permalink to &quot;3.1 Core Protocol Codec (`agentpay-core`) — Clean Pydantic V2 Models&quot;">​</a></h3><ul><li>We do <strong>not</strong> take a hard dependency on the third-party <code>x402</code> PyPI package.</li><li>We define <code>PaymentChallenge</code> and <code>PaymentAuthorization</code> models natively using <strong>Pydantic V2</strong>, adhering strictly to the x402 V2 standard.</li><li><strong>100% Byte-Level Parity:</strong> Serialization and deserialization guarantees are validated against standard test vectors (<code>specs/conformance/test-vectors/</code>).</li><li><strong>Benefit:</strong> Eliminates dependency hell, removes runtime black boxes, and guarantees optimal test execution speed and transparent debugging.</li></ul><h3 id="_3-2-network-interceptor-signing-lifecycle-agentpay-client-—-custom-orchestration" tabindex="-1">3.2 Network Interceptor &amp; Signing Lifecycle (<code>agentpay-client</code>) — Custom Orchestration <a class="header-anchor" href="#_3-2-network-interceptor-signing-lifecycle-agentpay-client-—-custom-orchestration" aria-label="Permalink to &quot;3.2 Network Interceptor &amp; Signing Lifecycle (`agentpay-client`) — Custom Orchestration&quot;">​</a></h3><ul><li>We implement an autonomous <code>httpx</code> transport interceptor.</li><li>The client strictly orchestrates the full financial lifecycle: $$\\text{Intercept 402} \\longrightarrow \\text{Policy Evaluate &amp; Reserve} \\longrightarrow \\text{Sign Authorization} \\longrightarrow \\text{Replay with PAYMENT-SIGNATURE} \\longrightarrow \\text{Commit or Release}$$</li></ul><h3 id="_3-3-upstream-interoperability-x402-interop-—-optional-extension" tabindex="-1">3.3 Upstream Interoperability (<code>x402-interop</code>) — Optional Extension <a class="header-anchor" href="#_3-3-upstream-interoperability-x402-interop-—-optional-extension" aria-label="Permalink to &quot;3.3 Upstream Interoperability (`x402-interop`) — Optional Extension&quot;">​</a></h3><ul><li>Provide helper utilities to convert between AgentPay native challenge/authorization objects and official <code>x402</code> library objects, ensuring frictionless interoperability if users choose to install both.</li></ul><hr><h2 id="_4-consequences-impact" tabindex="-1">4. Consequences &amp; Impact <a class="header-anchor" href="#_4-consequences-impact" aria-label="Permalink to &quot;4. Consequences &amp; Impact&quot;">​</a></h2><ul><li><strong>Positive Consequences:</strong><ul><li>Task T3.1 implementation workload remains strictly bounded ($\\le 3$ hours).</li><li>Two-phase reservation (<code>reserve -&gt; commit -&gt; release</code>) hooks directly into the HTTP transport lifecycle without hacks.</li><li>The Python SDK remains ultra-lightweight with fast cold-start times.</li></ul></li><li><strong>Risks &amp; Mitigation:</strong><ul><li><strong>Risk:</strong> Upstream x402 V2 specification introduces breaking schema modifications.</li><li><strong>Mitigation:</strong> Continuous automated conformance testing in GitHub Actions using cross-language JSON test vectors ensures early detection of schema drift.</li></ul></li></ul>',21)])])}const u=e(n,[["render",r]]);export{h as __pageData,u as default};
